-- Q10: Details of the last 20 completed matches
SELECT m.match_description, t1.team_name AS team1, t2.team_name AS team2, tw.team_name AS winner, m.victory_margin, m.victory_type, v.venue_name FROM matches m JOIN teams t1 ON m.team1_id = t1.team_id JOIN teams t2 ON m.team2_id = t2.team_id LEFT JOIN teams tw ON m.winner_id = tw.team_id JOIN venues v ON m.venue_id = v.venue_id WHERE m.is_completed = 1 ORDER BY m.match_date DESC LIMIT 20;